import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, spring } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@300;400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type MentalHealthFrontlinesProps = Record<string, any>;

const MentalHealthFrontlines: React.FC<MentalHealthFrontlinesProps> = ({
  titleText = "That’s why a grant would be so impactful for P & T therapy",
  backgroundColor = "#064e3b", // Deep Forest Green
  transparentBackground = false,
  primaryColor = "#34d399", // Emerald Green (Pop)
  accentColor = "#fbbf24", // Warm Amber (Complementary/Eye-catching)
  textColor = "#ecfdf5", // Soft Mint White
  fontSize = 110,
  durationInSeconds = 15,
}) => {
  useFontLoader(["Oswald", "Montserrat"]); // Bold Impact vs Clean Complementary

  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Handle Background Transparency
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Split text for staggered animation
  const words = titleText.split(" ");

  // --- Animations ---

  // 1. Line Animation (The "Bridge" Path)
  const lineProgress = spring({
    frame,
    fps,
    config: { damping: 200, stiffness: 50, mass: 2 },
    durationInFrames: fps * 4,
  });

  const pathLength = width * 1.8; 
  const strokeDashoffset = interpolate(
    lineProgress,
    [0, 1],
    [pathLength, 0]
  );

  // 2. Text Animation (Staggered Fade, Slide Up, & Scale Pop)
  const wordStagger = 4; // faster stagger for high impact
  
  // 3. Background Pulse (Subtle organic breath)
  const bgPulse = Math.sin(frame / 40) * 0.03 + 1; 
  const pulseOpacity = interpolate(
    frame,
    [0, 30],
    [0, 0.2],
    { extrapolateRight: "clamp" }
  );

  // 4. Mental Health Graphic Animation
  const graphicEnter = spring({
    frame: frame - 10,
    fps,
    config: { damping: 100, stiffness: 60, mass: 2 },
    durationInFrames: 50,
  });

  const graphicScale = interpolate(graphicEnter, [0, 1], [0.5, 1]);
  const graphicAlpha = interpolate(graphicEnter, [0, 1], [0, 0.15]); // Subtle background opacity
  const graphicFloat = Math.sin(frame / 50) * 15; // Gentle floating Y movement

  // SVG Path for the "Bridge/Journey" graph
  // Creates a smooth curve representing a bridge or hills
  const startY = height * 0.75;
  const bridgePeak = height * 0.45;
  
  // Dynamic path generation based on width
  const p1 = width * 0.25;
  const p2 = width * 0.5;
  const p3 = width * 0.75;
  
  const pathData = `
    M 0 ${startY} 
    C ${p1} ${startY} ${p1} ${bridgePeak} ${p2} ${bridgePeak}
    C ${p3} ${bridgePeak} ${p3} ${startY} ${width} ${startY}
  `;

  // Stylized Brain Paths (Mental Health Icon)
  const mentalHealthPaths = [
    // 1. Inner Fold Left (Accent - Index 0)
    "M 180,220 Q 210,180 230,240",
    // 2. Inner Fold Right (Accent - Index 1)
    "M 332,220 Q 302,180 282,240",
    // 3. Midline (Accent - Index 2)
    "M 256,160 L 256,380",
    // 4. Left Hemisphere Outline (Primary - Index 3)
    "M 246,130 C 160,130 110,200 110,280 C 110,360 170,410 246,390", 
    // 5. Right Hemisphere Outline (Primary - Index 4)
    "M 266,130 C 352,130 402,200 402,280 C 402,360 342,410 266,390",
    // 6. Lower Left Detail (Primary - Index 5)
    "M 150,300 Q 180,340 220,320",
    // 7. Lower Right Detail (Primary - Index 6)
    "M 362,300 Q 332,340 292,320"
  ];

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Montserrat", overflow: "hidden" }}>
      
      {/* Background Decor: Organic Circles */}
      {!transparentBackground && (
        <AbsoluteFill style={{ justifyContent: "center", alignItems: "center" }}>
          {/* Large warm glow */}
          <div
            style={{
              width: width * 0.9,
              height: width * 0.9,
              borderRadius: "50%",
              background: `radial-gradient(circle, ${primaryColor} 0%, transparent 60%)`,
              opacity: pulseOpacity,
              transform: `scale(${bgPulse})`,
              filter: "blur(40px)",
            }}
          />
          {/* Secondary Accent Blob */}
          <div
            style={{
              position: "absolute",
              top: "10%",
              left: "10%",
              width: width * 0.4,
              height: width * 0.4,
              borderRadius: "50%",
              background: `radial-gradient(circle, ${accentColor} 0%, transparent 70%)`,
              opacity: pulseOpacity * 0.5,
              transform: `translateY(${graphicFloat * -1}px)`,
              filter: "blur(60px)",
            }}
          />
        </AbsoluteFill>
      )}

      {/* Mental Health Graphic Layer */}
      <AbsoluteFill style={{ 
        justifyContent: "center", 
        alignItems: "center",
        zIndex: 5 
      }}>
        <svg
          width={width * 0.6}
          height={width * 0.6}
          viewBox="0 0 512 512"
          style={{
            opacity: graphicAlpha,
            transform: `scale(${graphicScale}) translateY(${graphicFloat}px)`,
          }}
        >
          {mentalHealthPaths.map((d, i) => (
            <path
              key={i}
              d={d}
              fill="none"
              stroke={i >= 3 ? primaryColor : accentColor} // Main outlines primary, details accent
              strokeWidth={i >= 3 ? 6 : 4}
              strokeLinecap="round"
              strokeLinejoin="round"
              style={{
                filter: "drop-shadow(0px 0px 10px rgba(255,255,255,0.1))"
              }}
            />
          ))}
          {/* Glowing Synapse Nodes */}
          {[
            { cx: 256, cy: 130 }, // Top Center
            { cx: 160, cy: 220 }, // Left Lobe
            { cx: 352, cy: 220 }  // Right Lobe
          ].map((dot, i) => (
             <circle 
                key={`dot-${i}`} 
                cx={dot.cx} 
                cy={dot.cy} 
                r={8} 
                fill={primaryColor}
                opacity={interpolate(frame, [10 + i*10, 30 + i*10], [0, 1], { extrapolateRight: "clamp" })} 
             />
          ))}
        </svg>
      </AbsoluteFill>

      {/* Main Text Container - zIndex increased to sit above graphics */}
      <AbsoluteFill style={{ 
        justifyContent: "center", 
        alignItems: "center", 
        padding: 40,
        zIndex: 20 
      }}>
        <div style={{ 
          display: "flex", 
          flexWrap: "wrap", 
          justifyContent: "center", 
          alignContent: "center",
          gap: `${fontSize * 0.2}px`,
          maxWidth: width * 0.95,
          height: "100%",
        }}>
          {words.map((word, i) => {
            const delay = i * wordStagger;
            const progress = spring({
              frame: frame - delay,
              fps,
              config: { damping: 12, stiffness: 100, mass: 0.8 },
            });

            const opacity = interpolate(progress, [0, 1], [0, 1]);
            const translateY = interpolate(progress, [0, 1], [50, 0]);
            const scale = interpolate(progress, [0, 1], [0.5, 1]);
            
            // Highlight specific keywords for "Impact"
            // Keywords: Grant, Impactful, P, &, T, Therapy
            const keywords = ["grant", "impactful", "p", "&", "t", "therapy"];
            const cleanWord = word.replace(/[^a-zA-Z&]/g, "").toLowerCase();
            const isHighlight = keywords.some(k => cleanWord === k || cleanWord.includes(k));
            
            const color = isHighlight ? accentColor : textColor;
            const fontFamily = isHighlight ? "Oswald" : "Montserrat";
            const fontWeight = isHighlight ? 700 : 400;
            const textTransform = isHighlight ? "uppercase" : "none";
            const currentFontSize = isHighlight ? fontSize * 1.2 : fontSize;

            return (
              <span
                key={i}
                style={{
                  opacity,
                  transform: `translateY(${translateY}px) scale(${scale})`,
                  fontSize: currentFontSize,
                  fontFamily,
                  color,
                  fontWeight,
                  textTransform: textTransform as any,
                  position: "relative",
                  display: "inline-block",
                  lineHeight: 1.1,
                  textShadow: isHighlight ? `0 0 20px ${backgroundColor}` : "0 4px 10px rgba(0,0,0,0.3)",
                }}
              >
                {word}
              </span>
            );
          })}
        </div>
      </AbsoluteFill>

      {/* The "Bridge" Graphic Line */}
      <AbsoluteFill style={{ zIndex: 15, pointerEvents: "none" }}>
        <svg
          width={width}
          height={height}
          viewBox={`0 0 ${width} ${height}`}
          style={{ overflow: "visible" }}
        >
          {/* Glow effect duplicate */}
          <path
            d={pathData}
            stroke={primaryColor}
            strokeWidth={10}
            fill="none"
            strokeDasharray={pathLength}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            strokeLinejoin="round"
            style={{ 
              opacity: 0.3, 
              filter: "blur(12px)" 
            }}
          />
          {/* Main Line */}
          <path
            d={pathData}
            stroke={primaryColor}
            strokeWidth={5}
            fill="none"
            strokeDasharray={pathLength}
            strokeDashoffset={strokeDashoffset}
            strokeLinecap="round"
            strokeLinejoin="round"
          />
          
          {/* Moving dot on the bridge */}
          {lineProgress < 0.99 && lineProgress > 0.01 && (
             <circle r={10} fill={accentColor}>
                <animateMotion 
                   dur={`${(fps * 4) / fps}s`} 
                   repeatCount="1"
                   path={pathData}
                   fill="freeze"
                   calcMode="spline"
                   keyTimes="0;1"
                   keySplines="0.4 0 0.2 1" // Smooth ease-out
                />
             </circle>
          )}
        </svg>
      </AbsoluteFill>

    </AbsoluteFill>
  );
};

export default MentalHealthFrontlines;